export const PRODUCTS = ['Rolls', 'Pallets', 'Other'];
export const ACTIONS = ['Work stopped', 'Area secured', 'Supervisor notified', 'Equipment taken out of service', 'Load reworked / stabilized', 'None', 'Other'];
export const FACTORS = ['Operator error', 'Poor visibility', 'Congestion / traffic', 'Improper loading / Offloading', 'Equipment issue', 'Process gap / SOP not followed', 'Lack of training', 'Communication breakdown', 'Other'];
export const RISKS = ['Low — Minor', 'Moderate — Recordable', 'High — Serious injury / Major damage', 'Critical — Life threatening / Fatal risk'];
