export const OSHA_TYPES = ['Injury', 'Skin disorder', 'Respiratory condition', 'Poisoning', 'Hearing loss', 'All other illnesses'];
export const TREATMENTS = ['None', 'First aid only', 'Medical treatment beyond first aid', 'Emergency room', 'Hospitalized (in-patient)'];
