  b.push(wp(wr('Classification (most serious outcome): ', { b: true })), BX(CLASSES, isRec(r) ? [classify(r)] : []));
  b.push(KV('Days away from work', r.daysAway ? String(Math.min(180, +r.daysAway)) : ''), KV('Days on job transfer or restriction', r.daysRestricted ? String(Math.min(180, +r.daysRestricted)) : ''));
  if (r.death === 'Y') b.push(KV('Date of death', us(r.dateOfDeath)));
