    injured: checked('injured')[0] || '', bodyPart: val('bodyPart'), injuryNature: val('injuryNature'), oshaType: val('oshaType'), treatment: val('treatment'),
    physician: val('physician'), treatmentFacility: val('treatmentFacility'), er: val('er'), hospitalized: val('hospitalized'), amputationEye: val('amputationEye'),
    recordable: val('recordable'), oshaCaseNo: val('oshaCaseNo'), privacyCase: f.privacyCase.checked ? 'Y' : '', daysAway: val('daysAway') === '' ? '' : Math.min(180, Math.max(0, Math.round(+val('daysAway')))),
