const fv = (m, v) => (m.unit === 'pct1' ? (typeof v === 'number' ? (v * 100).toFixed(1) + '%' : '—') : m.unit === 'num2' ? (typeof v === 'number' ? fmtNum(v, 2) : '—') : fmtV(m, v));
